This component shows a loading spinner then either results or an error message, but none of it is announced to screen readers:

```jsx
function SearchResults({ loading, error, results }) {
  if (loading) return <div className="spinner" />;
  if (error) return <div className="error-banner">{error}</div>;
  return <ul>{results.map(r => <li key={r.id}>{r.name}</li>)}</ul>;
}
```

This component loads and plays a Lottie animation on mount:

```jsx
function Celebration() {
  const [data, setData] = useState(null);
  useEffect(() => {
    fetch('/animations/confetti.json').then(r => r.json()).then(setData);
  }, []);
  return data ? <Lottie animationData={data} autoplay /> : null;
}
```

Respect prefers-reduced-motion.

After a search completes, new results appear below the search box, but keyboard/screen-reader users have no indication focus should move there:

```jsx
function Search() {
  const [results, setResults] = useState(null);
  async function onSearch(q) {
    const r = await fetchResults(q);
    setResults(r);
  }
  return (
    <div>
      <input onChange={e => onSearch(e.target.value)} />
      {results && <section><h2>Results</h2>{/* ...list... */}</section>}
    </div>
  );
}
```
